# POST /api/sheets/{sheetId}/today — change the sheet's today (the date everything on it goes by).
# Before the change takes effect, a SNAPSHOT line per person with the due-total on the day being left.
# With grace days set, the open periods past them are closed (auto=yes) before the rollup lines.
# A viewer may change nothing: refused before anything is read or written.
guard:
  class: net.officefloor.hq.app.setting.RefuseViewer
  next: validate
validate:
  class: net.officefloor.hq.app.sheet.ValidateSheetToday
  next: before
before:
  class: net.officefloor.hq.app.rollup.TakeRollup
  govern: [ transaction ]
  next: snapshot
snapshot:
  class: net.officefloor.hq.app.sheet.RecordSnapshots
  govern: [ transaction ]
  next: apply
apply:
  class: net.officefloor.hq.app.sheet.ApplySheetToday
  govern: [ transaction ]
  next: autoclose
autoclose:
  class: net.officefloor.hq.app.period.AutoClosePeriods
  govern: [ transaction ]
  next: rollup
rollup:
  class: net.officefloor.hq.app.rollup.RecordRollup
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.sheet.RespondWithSheet
    }

    /** The live sheet's creator and today, or null when it was never loaded. */
    private static String[] liveSheet(Connection c, String sheetId) throws SQLException {
        try (PreparedStatement ps = c.prepareStatement("SELECT created_by, today FROM PUBLIC.sheet WHERE id = ?")) {
            ps.setString(1, sheetId);
            try (ResultSet rs = ps.executeQuery()) {
                return rs.next() ? new String[] { rs.getString(1), rs.getObject(2, LocalDate.class).toString() } : null;
            }
        }
    }

    /** Copy the sheet's rows of every table from {@code source} (null: none) into a new schema. */
    private static void copy(Connection c, String source, String target, String sheetId) throws SQLException {
        List<String> tables = tables(c, LIVE);
        Set<String> inSource = source == null ? Set.of() : new HashSet<>(tables(c, source));
        String sheet = "'" + sheetId.replace("'", "''") + "'";
        try (Statement s = c.createStatement()) {
